WITH filtered_accounts AS (SELECT * FROM accounts WHERE (balance < 31000 AND balance >= 61000) OR balance <= 19000), Agg AS (SELECT CASE WHEN balance >= 68000 THEN 'high' WHEN balance >= 21000 THEN 'mid' ELSE 'low' END AS balance_bucket, COUNT(*) AS account_count, ROUND(STDDEV(balance), 2) AS stddev_balance FROM filtered_accounts GROUP BY CASE WHEN balance >= 68000 THEN 'high' WHEN balance >= 21000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, account_count, stddev_balance FROM Agg WHERE stddev_balance >= 56 ORDER BY stddev_balance DESC;
